insert into public.tool_pages (slug,title,description,intro,how_to,faq,seo_title,seo_description) values
('word-counter','Word Counter','Analyze writing and get statistics about words, characters, sentences, paragraphs, reading time, and keyword density.','Analyze your writing and get statistics in your browser. Live data helps you assess readability and keyword density to show repeated keywords. There is no need to send your draft to the server.','["Type or paste your text in the box.","Look at the data and keyword list.","The text is ready when you want it. Then you can copy the text."]','[{"question":"Is my text uploaded somewhere?","answer":"No. All text analysis is done in your browser."},{"question":"How do you calculate reading time?","answer":"This is done by estimating the average reading age of 200 words a minute."}]','Word Counter — Analyze Your Writing For Free','Analyze your writing and get instant statistics about words, characters, sentences, paragraphs, reading time, and keyword density.'),
('character-counter','Character Counter','Live character counts and totals. Count letters and characters with and without spaces. Also count words and lines.','Makes sure you stay within the character limit for posts, messages, snips and more. Our tool counts every character and reports characters without whitespace.','["Type or paste your text in the box.","Compare your text totals, with and without spaces.","Edit your text until it meets your character limit."]','[{"question":"Are symbols and punctuation counted?","answer":"Yes. They are characters too."},{"question":"Is my text saved?","answer":"No. All counting is done in the browser."}]','Character Counter — Letters, Characters and Spaces','Count letters and characters, with or without spaces. Also, count words and lines with this free private tool.'),
('website-word-counter','Web Page Word Counter','Submit a public URL to find the word count and estimate reading time.','Gather the readable text for editorial research from a public HTML page. We block private addresses, pages that are too large, and redirect chains to protect the service.','["Enter the final public page URL.","Click Count Words, and wait for the safe request.","Words and characters and reading time will be available."]','[{"question":"Can it read private pages?","answer":"No. Only public HTTP and HTTPS pages are available."},{"question":"Why can totals differ?","answer":"Some text can be JavaScript-rendered or hidden, and that can alter visible totals."}]','Website Word Counter — Analyze a Public URL','Word count and reading time for a public web page URL in a safe and quick way.'),
('auto-capitalize','Auto Capitalize Sentences','Upper case, lower case, title case, and fix case for complete sentences.','Sentence, title, upper, and lower modes help you clean up casing. View the original, copy the result, or create a downloadable UTF-8 text file of your result.','["Enter the text you want to transform.","Pick a casing option.","Copy or download the result."]','[{"question":"Does it recognize names?","answer":"No, since proper nouns are beyond automatic rules."},{"question":"Can I download the result?","answer":"Yes, as a plain UTF-8 text file."}]','Auto Capitalize Sentences — Free Case Converter','Online utility Upper case, lower case, title case, and fix case for complete sentences.'),
('compare-text','Compare Text','Compare two texts to show additions, deletions, and unchanged text.','Compare two texts, revisions, and additions at the word level. Added text is colored differently from removed text. The original text stays in the browser.','["Enter the original text in the left box.","Enter the revised text in the right box.","View colored added and removed text."]','[{"question":"Is it private?","answer":"Yes. We only do the word diff in your browser."},{"question":"What kind of diff is this?","answer":"This is a word level LCS diff."}]','Compare Texts - Fast Free Text Diff Tool','Use our tool to compare texts and see differences between added and removed text.'),
('pdf-to-word','PDF to Word Converter','PDF files to DOCX files.','Want text from a PDF to a Word file? This will help. Note: PDF page images, PDF complex formats, and visual elements will need your own review to be updated.','["Pick a PDF (max 20 MB).","Send it to start the DOCX file.","Pick and check the updated file."]','[{"question":"What happens to my files?","answer":"After processing, we delete your files and no later than 1 hour."},{"question":"What if my PDF is a scanned book?","answer":"PDF scans will need you to OCR before we can help."}]','Free PDF to Word File Converter','Text PDF to editable DOCX file conversion with fast and secure online processing.'),
('word-to-pdf','Word to PDF Converter','Create a portable PDF from a DOC or DOCX file.','Not a lot of people know that Word documents can actually be easily converted into Portable Document Format (PDF) files simply by using a server-side office engine. With all the different font styles and layouts that are involved in Word documents, the results may vary, so make sure to observe the result before making use of the file.','["Upload a DOC or DOCX file.","Initiate the conversion process.","Download the converted file."]','[{"question":"Is this service free to use?","answer":"Yes, as long as you follow the file size limit and fair use."},{"question":"For how long are files kept in your system?","answer":"They are deleted immediately after processing or the latest within one hour."}]','Word to PDF Converter — Free DOCX to PDF','Convert DOC and DOCX Word files to PDF online with secure temporary processing.'),
('pdf-to-png','PDF to PNG Converter','Render PDF pages as crisp PNG images.','Have you ever needed to extract images from a PDF file? Look no further! You can convert a PDF file and extract an image of each page by following these instructions.','["Upload a PDF file. Please ensure that the file size does not exceed 20 MB.","Select the option to convert PDF to PNG.","Download the converted file. The converted file will be in the format of a PNG file."]','[{"question":"I have a multi-page PDF file. How will you deliver the converted files?","answer":"You will receive a ZIP file which contains all the PNG images of each page of the PDF file."},{"question":"Do you care about the privacy of your documents?","answer":"Yes, all temporary files will be automatically deleted from our system within one hour."}]','PDF to PNG Converter — Free Page Images','Convert every PDF page to a crisp PNG image and download all pages in a ZIP archive.'),
('pdf-to-jpg','PDF to JPG Converter','PDF pages converted to compact JPG images.','PDF pages converted to compressed JPG images are easy to share and view on the web. Multi-page documents are returned in a ZIP file.','["Upload a PDF less than 20 MB.","Start JPG conversion.","Download ZIP file of JPG images."]','[{"question":"In what format are the JPGs received?","answer":"JPG files are compressed in a ZIP file."},{"question":"Does quality compression change?","answer":"JPG files are always compressed with lossy quality."}]','Free Page Converter -- PDF to JPG','PDF to JPG converter allows online conversion of compressed JPG images with the option to download multi-page documents in a ZIP file.'),
('pdf-to-excel','PDF to Excel Converter','PDF text is placed in the XLSX file.','Selectable text and spacing-separated columns will be converted to the XLSX file. Review the results for complex spacing-separated tables.','["Upload a PDF under 20 MB.","Start XLSX conversion.","Download XLSX file and check the table."]','[{"question":"Do I need OCR for this?","answer":"Only for scanned documents with images."},{"question":"Will formatting be the same?","answer":"Merged cells and complex layouts may require additional formatting."}]','PDF to Excel -- Convert to XLSX','Use the online tool to convert PDF text and tables to editable XLSX files.'),
('excel-to-pdf','Excel to PDF Converter','Export XLS or XLSX files to PDF.','Use an Office engine to export your Excel Workbook as a PDF for easy distribution or viewing!','["Select an XLS or XLSX file up to 20 MB.","Convert to PDF.","Download and check to see if your page breaks and scaling are how you want them."]','[{"question":"Are my formulas recalculated?","answer":"Our Office engine may recalculate formulas for your file."},{"question":"Are my uploads stored?","answer":"No! All temporary files are deleted within 1 hour."}]','Excel to PDF Converter','Use our online tool to convert XLS and XLSX documents to PDF while keeping your data secure!'),
('ppt-to-pdf','PPT to PDF Converter','Export your PowerPoint slides as a PDF.','Export your PPT or PPTX files as a PDF. Because a PDF is a static format, animating or layering things on top of one another are not possible, although slides will look as they do in PowerPoint as much as possible.','["Upload a PPT or PPTX file up to 20 MB.","Convert to PDF.","Download and look over your static slides."]','[{"question":"Will my animations show up?","answer":"No, a PDF is a static format and will not show animations."},{"question":"Will my fonts show up as intended?","answer":"Fonts that are not available may be substituted by our servers."}]','PPT to PDF Converter','Export your PPT and PPTX files to an easily shareable PDF document.'),
('pdf-to-ppt','PDF to PPT Converter','Convert PDF pages to PPT slides.','Add each rendered PDF page to a PPT slide. The page is added as an image which is preserved.','["Upload a PDF (up to 20MB).","Convert to PPTX.","Download a PPT slide deck with a slide for each PDF page."]','[{"question":"Is the text on the slides editable?","answer":"Pages are added as slide images, text is not editable."},{"question":"What slide size is used?","answer":"Widescreen layout is used for the slides."}]','PDF to PPTX Converter — PDF Slides to PPTX','Save PDF pages as PPTX slides in a Widescreen PPTX.'),
('jpg-to-pdf','JPG to PDF Converter','Combine JPG images into a PDF.','Create a PDF with up to twenty JPG images while oversized images are resized to fit PDF boundaries.','["Upload up to 20 JPG images (20 MB).","Create PDF.","Save PDF."]','[{"question":"How many JPG images can I upload?","answer":"20 maximum."},{"question":"Will combining the JPG images into a PDF reduce the quality?","answer":"No, the quality JPG images will be embedded into the PDF without compression."}]','JPG to PDF Converter – Combine JPGs','Combine JPG images into a PDF online with a 20 MB file size limit.'),
('png-to-pdf','PNG to PDF Converter','Convert multiple single or batch PNG files to PDF.','Convert 20 PNG files to PDF. Our online tool works to optimize larger page sizes as well as maintain file transparency.','["Select or drag and drop 20 PNG files, up to 20 MB.","Create PDF.","Combine PDF."]','[{"question":"How many PNG files can I combine?","answer":"You may combine up to 20 files."},{"question":"How long will files be stored?","answer":"Files will be deleted within 1 hour of processing, usually much sooner."}]','Convert PNG to PDF Online for FREE','Easily convert single or multiple PNG files to PDF. No cost, no catches!'),
('heic-to-jpg','HEIC to JPG Converter','Convert HEIC and HEIF photos into widely compatible JPG images.','Convert an HEIC or HEIF photo into a high-quality JPG that opens easily in browsers, editors, and older devices. Upload one image up to 20 MB; the server validates the HEIC container, limits decoded images to 40 megapixels, and removes temporary files immediately after conversion.','["Upload one HEIC or HEIF image up to 20 MB.","Start the secure conversion to a high-quality JPG.","Download the JPG and check the result."]','[{"question":"Why convert HEIC to JPG?","answer":"JPG works in more browsers, editors, websites, and older devices, while HEIC is commonly used by Apple devices to save storage space."},{"question":"Will the JPG look exactly the same?","answer":"The converter uses a high-quality JPG setting, but JPG is a lossy format and may be larger than the HEIC original."},{"question":"What happens to my photo?","answer":"The photo is used only for conversion and is deleted from temporary storage immediately after the response is prepared."}]','Free HEIC to JPG Converter — Convert HEIF Photos','Convert HEIC and HEIF photos to high-quality JPG images online with secure temporary processing.'),
('image-compressor','Image Compressor','Make JPG, PNG, and WebP images smaller without uploading them.','Compress an image directly in your browser. Choose the output format, quality, and maximum dimensions, then compare the original and compressed sizes before downloading. Your image stays on your device throughout the process.','["Upload a JPG, PNG, or WebP image up to 20 MB.","Choose an output format, quality, and maximum dimensions.","Compress the image, compare the file sizes, and download the result."]','[{"question":"Is my image uploaded?","answer":"No. Compression runs in your browser, so the image never leaves your device."},{"question":"Which format makes the smallest file?","answer":"WebP usually produces the smallest web-ready file. JPG is widely compatible, while PNG is best when you need lossless quality or transparency."},{"question":"Why can a compressed image be larger?","answer":"A high quality setting, lossless PNG output, or converting an already optimized image can create a larger result. Lower the quality or dimensions and try again."}]','Free Image Compressor — Reduce JPG, PNG & WebP Size','Compress JPG, PNG, and WebP images online, adjust quality and dimensions, and download a smaller file without uploading it.'),
('video-compressor','Video Compressor','Reduce MP4, MOV, WebM, and MKV video sizes for easier sharing.','Compress a video into a browser-friendly MP4 with a choice of quality, balanced, or small-file settings. Upload one video up to 100 MB, keep the page open while it is processed, and download the result when it is ready.','["Upload one MP4, MOV, WebM, or MKV video up to 100 MB.","Choose Higher quality, Balanced, or Small file.","Compress the video and download the MP4 result."]','[{"question":"Which video formats can I upload?","answer":"You can upload MP4, MOV, WebM, and MKV files up to 100 MB. The downloaded result is an MP4."},{"question":"Will compression reduce quality?","answer":"Video compression trades some visual detail for a smaller file. Choose Higher quality to keep more detail or Small file when size matters most."},{"question":"How long is my video kept?","answer":"The temporary input and output files are removed as soon as the download response finishes."}]','Free Video Compressor — Reduce MP4, MOV & WebM Size','Compress MP4, MOV, WebM, and MKV videos online and download a smaller browser-friendly MP4 file.'),
('color-wheel','Color Wheel','Pick a color and generate complements, analogs, triads, monotones, etc.','Pick the hue and saturation and lightness to visually and copy the HEX, RGB, HSL for production. Generate color relationships without sending your selections to a server.','["Pick a color and set the lightness.","Pick the relational palette.","Copy the color or some of the palette."]','[{"question":"What is the preferred CSS choice?","answer":"All formats work, but HSL is the most adjustable."},{"question":"Are the palettes kept?","answer":"No, you must copy the colors."}]','Color Wheel — Color Picker, Color Codes, Color Relations','Pick a color, see it''s HEX, RGB, HSL and generate color relations.'),
('random-color-generator','Random Color Generator','Choose random colors and generate swatches with HEX, RGB, HSL values.','Design with random colors! Great for design ideas or writing prompts. Pick a set of swatches, lock the swatches you want to keep and get ready-to-use HEX, RGB, and HSL values. Everything is done in your browser.','["Press the \"Generate\" button or hit the space bar.","Hit the lock button to keep a swatch for the next round of colors.","Choose a swatch and hit copy to get its color values."]','[{"question":"How does shuffling colors work?","answer":"Each color channel is populated with a value for an even distribution of colors and uses a securely seeded random value."},{"question":"How do I keep a color?","answer":"Lock the color swatch to keep it, the un-locked swatches will be changed."}]','Generate Random Colors - Color Picker Tool','Instantly generate random colors for your design projects! Choose swatches and get HEX, RGB, and HSL color values'),
('image-to-text','Image to Text Converter','Scan images and screenshots to extract editable text using our in-browser OCR.','Use OCR in your browser to extract editable text from images and screenshots. The image is never uploaded to our server.','["Upload an image in JPG, PNG, or WEBP format (up to 15 MB).","Click on the extraction button and watch as the text is recognized.","The extracted editable text is ready. You can copy or download it."]','[{"question":"Is my image uploaded?","answer":"No. The text recognition happens in your browser so the image stays on your device."},{"question":"Why is some text extracted incorrectly?","answer":"There are many reasons as to why the extracted text is not accurate. For example, the image could have a low resolution, contain handwriting, or have a noisy background. To get the correct text, use images that are clear and straight."}]','Image to Text Converter — Free Online OCR','Extract editable text from images and screenshots with private in-browser OCR. No upload required.')
insert into public.content_pages (slug,title,description,body,seo_title) values
('privacy-policy','Privacy Policy','How Figimi Tools handles text, uploaded files, analytics, advertising, and contact information.',E'## Overview\n\nText tools run locally in your browser.\n\n## File conversion and retention\n\nUploaded files are used only for the requested conversion, processed in isolated temporary storage, removed immediately after the response whenever possible, and automatically deleted no later than one hour after upload. Files are not used for advertising, model training, or resale.\n\n## Analytics and advertising\n\nIf enabled, Google Analytics, Google Tag Manager, and Google AdSense may process cookies and limited device or usage information. Cloudflare may process network data for security and delivery.\n\n## Your choices\n\nYou can block nonessential cookies in your browser and contact us to request access, correction, or deletion of personal data we hold. Last updated July 22, 2026.','Privacy Policy'),
('terms-of-service','Terms of Service','Rules and conditions for using Figimi Tools and its free conversion services.',E'## Permitted use\n\nUse the service lawfully and only with files you are authorized to process. Do not overload, probe, or bypass service controls.\n\n## Conversion limits\n\nResults may lose formatting, formulas, fonts, or metadata. Keep your original and inspect the output.\n\n## Disclaimer\n\nThe service is provided as is, without a guarantee of availability or fitness for a particular purpose.','Terms of Service'),
('about','About Us','Why Figimi Tools builds fast, private, and accessible utilities for everyday digital work.',E'## Useful software should feel simple\n\nFigimi Tools provides focused utilities for writers, students, designers, and office teams. We explain each tool, disclose its limits, support mobile devices, and avoid unnecessary registration.\n\n## Privacy and quality\n\nBrowser tools keep text on your device. File tools use short-lived server processing. We publish original guides and recommend checking important output against the source.','About Figimi Tools')
insert into public.posts (id,title,slug,meta_description,seo_title,category,tags,author,body,status,published_at)
